import { useCallback, useEffect, useRef, useState } from 'react';import { Landmark, X } from 'lucide-react';
import ChatMessage from './ChatMessage';
import ChatInput from './ChatInput';
import QuickOptions from './QuickOptions';
import ProgressIndicator from './ProgressIndicator';
import StepFieldCard from './StepFieldCard';
import ApplicationSummary from './ApplicationSummary';
import Button from '../common/Button';
import useChat from '../../hooks/useChat';
import useApplicationSession, { SESSION_STAGE } from '../../hooks/useApplicationSession';
import { FIELD_TYPES } from '../../config/applicationSteps';
import { submitApplicationToAWS } from '../../services/awsService';

export default function AssistantPanel({ onClose }) {
  const { messages, addBotMessage, addUserMessage } = useChat();
  const session = useApplicationSession();
  const bodyRef = useRef(null);
  const lastPromptedStepId = useRef(null);
  const summaryAnnounced = useRef(false);
  const [submitting, setSubmitting] = useState(false);

  // Note: the initial greeting lives in the dedicated welcome card below,
  // not as a chat bubble, so it isn't shown twice once messages start.

  // Ask the current step's question whenever the engine moves to a new step.
  useEffect(() => {
    if (session.stage !== SESSION_STAGE.IN_PROGRESS || !session.currentStep) return;
    if (lastPromptedStepId.current === session.currentStep.id) return;
    lastPromptedStepId.current = session.currentStep.id;
    addBotMessage(session.currentStep.assistantPrompt);
  }, [session.stage, session.currentStep, addBotMessage]);

  // Announce the transition into the review screen, once per arrival.
  useEffect(() => {
    if (session.stage === SESSION_STAGE.SUMMARY && !summaryAnnounced.current) {
      summaryAnnounced.current = true;
      addBotMessage("That's everything I need — here's a summary to check over.");
    }
    if (session.stage === SESSION_STAGE.IN_PROGRESS) {
      summaryAnnounced.current = false;
    }
  }, [session.stage, addBotMessage]);

  // Auto-scroll to the latest content.
  useEffect(() => {
    if (bodyRef.current) {
      bodyRef.current.scrollTop = bodyRef.current.scrollHeight;
    }
  }, [messages, session.stage]);

  const commitAnswer = (rawValue, displayLabel) => {
    addUserMessage(displayLabel);
    const result = session.submitAnswer(rawValue);
    if (!result.valid) {
      addBotMessage(result.error);
    }
  };

  const handleQuickOptionSelect = (value) => {
    const option = session.currentStep.options.find((o) => o.value === value);
    commitAnswer(value, option?.label ?? value);
  };

  const handleFieldCardSubmit = (rawValue) => {
    const label =
      session.currentStep.type === FIELD_TYPES.CURRENCY
        ? `$${rawValue}`
        : `${rawValue.firstName ?? ''} ${rawValue.lastName ?? ''}`.trim();
    commitAnswer(rawValue, label || '(no answer)');
  };

  // Free-text fallback: lets the user type instead of clicking, without a
  // real NLU model wired up yet (that lands in Phase 4). Does simple,
  // deterministic matching so manual text input is genuinely usable today.
  const handleFreeText = (text) => {
    const step = session.currentStep;
    if (!step) return;

    if (step.type === FIELD_TYPES.CHOICE) {
      const normalized = text.trim().toLowerCase();
      const match = step.options.find(
        (opt) =>
          opt.label.toLowerCase() === normalized ||
          opt.value.toLowerCase() === normalized ||
          opt.label.toLowerCase().includes(normalized) ||
          normalized.includes(opt.label.toLowerCase().split(' ')[0])
      );
      addUserMessage(text);
      if (match) {
        const result = session.submitAnswer(match.value);
        if (!result.valid) addBotMessage(result.error);
      } else {
        addBotMessage(
          "Sorry, I didn't quite catch that — please choose one of the options above, or try rephrasing."
        );
      }
      return;
    }

    if (step.type === FIELD_TYPES.NAME) {
      const parts = text.trim().split(/\s+/);
      if (parts.length < 2) {
        addUserMessage(text);
        addBotMessage('Could you give me both your first and last name?');
        return;
      }
      const [firstName, ...rest] = parts;
      commitAnswer({ firstName, lastName: rest.join(' ') }, text);
      return;
    }

    // CURRENCY and anything else — hand the raw text straight to the
    // validator, which strips $ and commas.
    commitAnswer(text, text);
  };

  const handleSubmitApplication = async () => {
    setSubmitting(true);
    try {
      await submitApplicationToAWS(session.answers);
      session.markSubmitted();
    } catch {
      addBotMessage(
        "I'm having trouble submitting right now. You can try again, or continue using the form manually."
      );
    } finally {
      setSubmitting(false);
    }
  };

  const isChoiceStep = session.currentStep?.type === FIELD_TYPES.CHOICE;
  const isFieldCardStep =
    session.currentStep?.type === FIELD_TYPES.CURRENCY || session.currentStep?.type === FIELD_TYPES.NAME;
  const showPreviousLink = session.currentIndex > 0;

  return (
    <div className="rl-panel" role="dialog" aria-label="Responsive Lending AI Loan Assistant" aria-modal="false">
      <header className="rl-panel__header">
        <div className="rl-panel__header-left">
          <span className="rl-panel__avatar" aria-hidden="true">
            <Landmark size={18} strokeWidth={2.3} />
          </span>
          <div className="rl-panel__titles">
            <div className="rl-panel__title">Responsive Lending</div>
            <div className="rl-panel__subtitle">AI Loan Assistant</div>
          </div>
        </div>
        <button type="button" className="rl-panel__close" onClick={onClose} aria-label="Close chat">
          <X size={16} strokeWidth={2.4} />
        </button>
      </header>

      {session.stage === SESSION_STAGE.IN_PROGRESS && (
        <ProgressIndicator current={session.currentStepNumber} total={session.totalSteps} />
      )}

      <div className="rl-panel__body" ref={bodyRef} aria-live="polite">
        {session.stage === SESSION_STAGE.WELCOME && (
          <div className="rl-welcome">
            <div className="rl-welcome__header">
              <span className="rl-welcome__avatar" aria-hidden="true">
                <Landmark size={16} strokeWidth={2.3} />
              </span>
              <span className="rl-welcome__name">Responsive Lending Assistant</span>
            </div>
            <p className="rl-welcome__text">
              Hi! I'm here to help you complete your loan application. We can do this together,
              step by step.
            </p>
            <Button variant="primary" block onClick={session.start}>
              Start Application
            </Button>
          </div>
        )}

        {messages.map((m) => (
          <ChatMessage key={m.id} sender={m.sender} text={m.text} />
        ))}

        {session.stage === SESSION_STAGE.IN_PROGRESS && isChoiceStep && (
          <>
            <QuickOptions options={session.currentStep.options} onSelect={handleQuickOptionSelect} />
            {showPreviousLink && (
              <div className="rl-quick-options" style={{ paddingLeft: 34 }}>
                <button type="button" className="rl-summary__edit-link" onClick={session.goToPrevious}>
                  ← Previous question
                </button>
              </div>
            )}
          </>
        )}

        {session.stage === SESSION_STAGE.IN_PROGRESS && isFieldCardStep && (
          <StepFieldCard
            step={session.currentStep}
            error={session.fieldError}
            onSubmit={handleFieldCardSubmit}
            onBack={session.goToPrevious}
            showBack={showPreviousLink}
          />
        )}

        {session.stage === SESSION_STAGE.SUMMARY && (
          <ApplicationSummary
            steps={session.visibleSteps}
            answers={session.answers}
            onEdit={session.editStep}
            onContinue={handleSubmitApplication}
          />
        )}

        {session.stage === SESSION_STAGE.SUBMITTED && (
          <div className="rl-submitted">
            <div className="rl-submitted__icon" aria-hidden="true">
              ✓
            </div>
            <h3 className="rl-submitted__title">Application submitted</h3>
            <p className="rl-submitted__text">
              Thanks — we've received your details. One of our lending specialists will be in touch
              shortly to discuss your options.
            </p>
          </div>
        )}

        {submitting && <div className="rl-system-note">Submitting your application…</div>}
      </div>

      {session.stage === SESSION_STAGE.IN_PROGRESS && (
        <ChatInput onSend={handleFreeText} placeholder="Type your answer…" />
      )}
    </div>
  );
}
